function camelToKebab(value) {
    return value.replace(
        /[A-Z]/g,
        (character) => `-${character.toLowerCase()}`
    );
}

export function getBreakpointValue(name) {
    if (!name) {
        return null;
    }

    const value = getComputedStyle(document.documentElement)
        .getPropertyValue(`--breakpoint-${name}`)
        .trim();

    return value || null;
}

export function applyCarouselCustomProperties(emblaNode) {
    Object.entries(emblaNode.dataset).forEach(([name, value]) => {
        if (!value) {
            return;
        }

        const isSlideSize = name.startsWith('slideSize');
        const isSlideSpacing = name.startsWith('slideSpacing');

        if (!isSlideSize && !isSlideSpacing) {
            return;
        }

        emblaNode.style.setProperty(`--${camelToKebab(name)}`, value);
    });

    const inactiveColumns = emblaNode.dataset.inactiveColumns;

    if (inactiveColumns) {
        emblaNode.style.setProperty('--inactive-columns', inactiveColumns);
    }
}

export function getCarouselBreakpoints(emblaNode) {
    const disableFromName = emblaNode.dataset.disableFrom;
    const disableFromValue = getBreakpointValue(disableFromName);

    if (!disableFromValue) {
        return {};
    }

    return {
        [`(min-width: ${disableFromValue})`]: {
            active: false,
        },
    };
}
