/**
 * Loop autoplayed video a defined number of times.
 *
 * @module patterns/video/video
 * @author Web Development
 * @copyright City St George's, University of London
 */

import { createHTMLElement } from '../../util';

const className = 'js-emb-vid-v26';

/**
 * Loop video as et number of times
 *
 * @param {element} video - Figure with the 'embedded-video--autoplay' class.
 * @param {element} videoEl - HTML video element.
 * @param {number} maxPlays - Maximum number of times video should play.
 */

function prepareVideo(video) {
    const coverImage = video.querySelector('.cover-image__container');
    const playButton = video.querySelector('.cover-image__button');
    const insertVideoHere = video.querySelector('.youtube-video__wrapper');
    const youtubeVideoId = video.getAttribute('data-youtube-id');

    playButton.addEventListener('click', () => {
        coverImage.remove();

        const youtubeVideo = createHTMLElement('iframe', [
            {
                label: 'src',
                val: `https://www.youtube-nocookie.com/embed/${youtubeVideoId}?rel=0&iv_load_policy=3&autoplay=1`,
            },
            {
                label: 'frameborder',
                val: '0',
            },
            {
                label: 'allow',
                val: 'accelerometer; encrypted-media; gyroscope; picture-in-picture; autoplay',
            },
            {
                label: 'allowfullscreen',
                val: '',
            },
            {
                label: 'title',
                val: `YouTube video: ${video.getAttribute(
                    'data-youtube-caption'
                )}`,
            },
        ]);

        video.setAttribute('data-video-loaded', 'true');

        insertVideoHere.append(youtubeVideo);
    });
}

export default {
    launchFn: prepareVideo,
    launchQuery: `.${className}`,
};
